    /* 출근일시 change 이벤트 */
    onChangeWrkStrdt: function(datefield, newDate, oldDate, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        if (!newDate)
        return;

        //PARAM SET
        var params = {
            //공통
            hrHrpmCompId : SecurityUtils.getPrincipal().hrHrpmCompId, //회사
            hrHrpmEmpId : SecurityUtils.getPrincipal().hrHrpmEmpId, //사번
            stcd : Constants.stcd.NORMAL, //상태
            searchDate : DateUtils.getDate(new Date()), //오늘날짜
            wrkDt : DateUtils.getDate(newDate),
            noPaging : true,
        };

        Ext.Ajax.request({
            headers : {
                serviceId : 'HwmDaySvc.findAllHwmDayWebGrid', // 2019.06.25 13:40 등록완료 (10시방향 그리드만)
                viewId : me.getViewId(),
                scope : me
            },
            jsonData : params,
            success : function(response) {
                var res = Ext.JSON.decode(response.responseText);
                //총 시간외근무시간 표시 (금월/금주)
                if (res.totAdmtOvtHod) {
                    refs.totOvtHodMonthHr.setValue(res.totAdmtOvtHod.totOvtHodMonthHr);
                    refs.totOvtHodWeekHr.setValue(res.totAdmtOvtHod.totOvtHodWeekHr);
                }

                if (res.page.content.length > 0 && res.page.content[0].wrkStrdt) {
                    var wrkInfo = {
                        wrkEdt : DateUtils.parseDate(res.page.content[0].wrkEdt),
                        wrkStrtm : DateUtils.getTimeFormat(res.page.content[0].wrkStrtm, 'H:i:s'),
                        wrkEdtm : DateUtils.getTimeFormat(res.page.content[0].wrkEdtm, 'H:i:s'),
                    };
                    vm.set('wrkInfo', wrkInfo);
                } else {
                    Ext.Msg.alert('알림', '해당 날짜에 출/퇴근 기록이 없습니다 <br> 정정 신청 후 진행하시기 바랍니다.');
                    datefield.setValue('');
                    vm.set('wrkInfo', '');
                }
            }
        });
    },

    /* 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            approvalLineGrid = refs.approvalLineGrid, 	// 결재선
            afterchangeform = refs.frmDetail,
            initialConfig = component.config, 			// 화면초기데이터
            command = initialConfig.command,
            aprHistData = initialConfig.aprHistData, 	// 결재이력데이터
            // 결재함(ExpNteApr02)에서는 docData,
            // 휴일근무신청(HwmHodRept01)에서는 aprHistData.docData
            docData = (aprHistData) ? aprHistData.docData : initialConfig.docData, 				// 문서데이터
            afterchange = docData.afterchange,
            edocCd = 'HwmHodRept71', 					// 문서코드
            edocNm = '휴일근무 보고서',
            aprHistId = initialConfig.aprHistId, 		// 결재내역ID
            userId = SecurityUtils.getPrincipal().hrHrpmEmpId, // 사용자ID
            record = initialConfig.record; 				// 결재함 목록에서 선택한 레코드

            vm.set('docCd', edocCd);
        vm.set('docNm', edocNm);
        vm.set('aprHistId', aprHistId);
        vm.set('afterchange', afterchange);
        vm.set('record', record);

        var hodStrtm = afterchange.hodStrtm,
            hodEdtm = afterchange.hodEdtm,
            wrkStrtm = afterchange.wrkStrtm,
            wrkEdtm = afterchange.wrkEdtm;
        afterchange.hodStrtm = DateUtils.encodeDate(DateUtils.getTimeToDate(hodStrtm),"H:i");
        afterchange.hodEdtm = DateUtils.encodeDate(DateUtils.getTimeToDate(hodEdtm),"H:i");
        afterchange.wrkStrtm = DateUtils.encodeDate(DateUtils.getTimeToDate(wrkStrtm),"H:i:s");
        afterchange.wrkEdtm = DateUtils.encodeDate(DateUtils.getTimeToDate(wrkEdtm),"H:i:s");

        var aplHodDt = afterchange.aplHodDt,
            hodStrdt = afterchange.hodStrdt,
            hodEdt = afterchange.hodEdt,
            wrkStrdt = afterchange.wrkStrdt,
            wrkEdt = afterchange.wrkEdt;
        afterchange.aplHodDt = DateUtils.parseDate(aplHodDt);
        afterchange.hodStrdt = DateUtils.parseDate(hodStrdt);
        afterchange.hodEdt = DateUtils.parseDate(hodEdt);
        afterchange.wrkStrdt = DateUtils.parseDate(wrkStrdt);
        afterchange.wrkEdt = DateUtils.parseDate(wrkEdt);
        afterchange.aplDvcdNm = CodeUtils.getText('HWM009', afterchange.aplDvcd);

        me.fnInitComponentForm(afterchangeform);

        me.setAprHistId(aprHistId); // 결재이력아이디
        me.setRecord(record); 		// 동시성 제어를 하기 위한 용도로 Config에 저장함
        me.setCommand(command); 	// 결재처리 커맨드

        // 결재문서 초기화 설정
        ApprovalBoxSvc.setup({
            command : command, 		// 결재선구분커맨드
            viewModel : vm,
            edocCd : edocCd, 		// 전자문서관리화면에 설정된 문서코드: 화면ID를 사용
            aprHistId : aprHistId, 	// 결재이력ID
            scope : me
        });

        afterchangeform.setValues(afterchange);

        var rgdt = (aprHistData) ? record.apfAplDtm : record.fstRgDtti;		// 휴일근무신청(apfAplDtm) , 결재함(fstRgDtti)
        refs.rgdt.setHtml(rgdt.substr(0,10));

        refs.hodStrtm.el.select('.x-error-el').setStyle('margin','0px');
        refs.hodEdtm.el.select('.x-error-el').setStyle('margin',	'0px');
        refs.hodStrtm.el.select('.x-error-el').setStyle('height','0px');
        refs.hodEdtm.el.select('.x-error-el').setStyle('height',	'0px');
    }

